#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

struct Edge {
    int from, to, capacity, flow;
};

const int INF = 1 << 29;
const int MAXN = 500;

int n, t, xb, yb;
bool m[11][11];
int temp[11][11], kaps[11][11];
vector<int> g[MAXN];
vector<Edge> e;
int dist[MAXN], ptr[MAXN];

int find_path(int x1, int y1, int x2, int y2) {
    queue<pair<int, pair<int, int>>> q;
    q.push({0, {x1, y1}});
    int dist_map[11][11];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            dist_map[i][j] = INF;
    while (!q.empty()) {
        auto v = q.front(); q.pop();
        int vdist = v.first;
        int x = v.second.first, y = v.second.second;
        dist_map[x][y] = vdist;
        if (x > 0 && m[x - 1][y] && dist_map[x - 1][y] > dist_map[x][y] + 1 && ((x - 1 == x2 && y == y2 && temp[x - 1][y] >= dist_map[x][y] + 1) || !(x - 1 == x2 && y == y2) && temp[x - 1][y] > dist_map[x][y] + 1))
            q.push({vdist + 1, {x - 1, y}});
        if (y > 0 && m[x][y - 1] && dist_map[x][y - 1] > dist_map[x][y] + 1 && ((x == x2 && y - 1 == y2 && temp[x][y - 1] >= dist_map[x][y] + 1) || !(x == x2 && y - 1 == y2) && temp[x][y - 1] > dist_map[x][y] + 1))
            q.push({vdist + 1, {x, y - 1}});
        if (x < n - 1 && m[x + 1][y] && dist_map[x + 1][y] > dist_map[x][y] + 1 && ((x + 1 == x2 && y == y2 && temp[x + 1][y] >= dist_map[x][y] + 1) || !(x + 1 == x2 && y == y2) && temp[x + 1][y] > dist_map[x][y] + 1))
            q.push({vdist + 1, {x + 1, y}});
        if (y < n - 1 && m[x][y + 1] && dist_map[x][y + 1] > dist_map[x][y] + 1 && ((x == x2 && y + 1 == y2 && temp[x][y + 1] >= dist_map[x][y] + 1) || !(x == x2 && y + 1 == y2) && temp[x][y + 1] > dist_map[x][y] + 1))
            q.push({vdist + 1, {x, y + 1}});
    }
    return dist_map[x2][y2];
}

void add_link(int u, int v, int cap) {
    e.push_back({u, v, cap, 0});
    g[u].push_back((int)e.size() - 1);
    e.push_back({v, u, 0, 0});
    g[v].push_back((int)e.size() - 1);
}

bool bfs_check() {
    queue<int> q;
    q.push(0);
    memset(dist, -1, sizeof(dist));
    dist[0] = 0;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (auto id : g[v]) {
            int to = e[id].to;
            if (dist[to] == -1 && e[id].flow < e[id].capacity) {
                dist[to] = dist[v] + 1;
                q.push(to);
            }
        }
    }
    return dist[n * n * 2 + 1] != -1;
}

int flow_send(int v, int flow) {
    if (v == n * n * 2 + 1 || flow == 0) return flow;
    for (; ptr[v] < (int)g[v].size(); ptr[v]++) {
        int id = g[v][ptr[v]];
        int to = e[id].to;
        if (dist[to] == dist[v] + 1 && e[id].flow < e[id].capacity) {
            int pushed = flow_send(to, min(flow, e[id].capacity - e[id].flow));
            if (pushed > 0) {
                e[id].flow += pushed;
                e[id ^ 1].flow -= pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int compute_max_flow_value() {
    int total_flow = 0;
    while (bfs_check()) {
        memset(ptr, 0, sizeof(ptr));
        while (int pushed = flow_send(0, INF))
            total_flow += pushed;
    }
    return total_flow;
}

int main() {
    cin >> n >> t;
    queue<pair<int, pair<int, int>>> q;
    char c;
    int k = 1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> c;
            temp[i][j] = t;
            if (c == 'Z') {
                xb = i; yb = j;
                m[i][j] = false;
            } else if (c == 'Y') {
                m[i][j] = false;
            } else {
                m[i][j] = true;
            }
            add_link(0, k++, (c == 'Z' || c == 'Y') ? 0 : c - '0');
        }
    }
    int base = n * n + 1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> c;
            if (c >= '0' && c <= '9') kaps[i][j] = c - '0';
            add_link(base + i * n + j, n * n * 2 + 1, (c == 'Z' || c == 'Y') ? 0 : c - '0');
        }
    }
    q.push({0, {xb, yb}});
    while (!q.empty()) {
        auto v = q.front(); q.pop();
        int vdist = v.first;
        int x = v.second.first, y = v.second.second;
        temp[x][y] = vdist;
        if (x > 0 && vdist + 1 < temp[x - 1][y] && m[x - 1][y]) q.push({vdist + 1, {x - 1, y}});
        if (y > 0 && vdist + 1 < temp[x][y - 1] && m[x][y - 1]) q.push({vdist + 1, {x, y - 1}});
        if (x < n - 1 && vdist + 1 < temp[x + 1][y] && m[x + 1][y]) q.push({vdist + 1, {x + 1, y}});
        if (y < n - 1 && vdist + 1 < temp[x][y + 1] && m[x][y + 1]) q.push({vdist + 1, {x, y + 1}});
    }
    int total_nodes = n * n;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int k1 = total_nodes * (i * n + j);
            for (int z = 0; z < n; z++) {
                for (int w = 0; w < n; w++) {
                    if (m[i][j] && m[z][w] && way(i, j, z, w) <= t)
                        add_link(base + i * n + j, (z * n + w) + total_nodes, INF);
                }
            }
        }
    }
    cout << compute_max_flow_value() << "\n";
    return 0;
}
